parameters.functionCode:
const body = $input.first().json.body || $input.first().json;
const change = {
  employeeName: body.employeeName || '',
  employeeEmail: body.employeeEmail || '',
  employeeId: body.employeeId || '',
  department: body.department || '',
  changeType: body.changeType || '',
  previousValue: body.previousValue || '',
  newValue: body.newValue || '',
  effectiveDate: body.effectiveDate || '',
  approvedBy: body.approvedBy || '',
  reason: body.reason || '',
  submittedAt: new Date().toISOString()
};

const errors = [];
if (!change.employeeName) errors.push('Missing employee name');
if (!change.employeeEmail) errors.push('Missing employee email');
if (!change.changeType) errors.push('Missing change type');
if (!change.effectiveDate) errors.push('Missing effective date');
if (!change.approvedBy) errors.push('Missing approver');

return [{ json: { ...change, isValid: errors.length === 0, validationErrors: errors } }];

